# Connector-extracted archived configuration; not an original HTTP byte capture.
# Source: https://github.com/geographika/mappyfile/blob/28716ec134d30ab5c7f0da5e28d7b3f100a3737d/tests/mapfiles/large_map1.map
# Two source spans are concatenated below: MAP/WEB header, then the complete varosr LAYER.
# No source coordinate values or feature geometry were returned by this configuration file.

MAP
NAME kobanya
EXTENT 653350 234700 663500 240650
SIZE 600 600
IMAGETYPE png
SHAPEPATH "/web/html/x/data"
#SHAPEPATH "/home/html/x/data"
FONTSET "/web/html/x/fonts.lst"
#FONTSET "/home/html/x/fonts.lst"
SYMBOLSET "/web/html/x/x.sym"
#SYMBOLSET "/home/html/x/x.sym"
UNITS meters
#TEMPLATEPATTERN ".*\.html"
CONFIG "MS_ERRORFILE"  "/web/html/x/tmp/error.txt"
#CONFIG "MS_ERRORFILE"  "/home/html/x/tmp/error.txt"
DEBUG 5
INTERLACE OFF
RESOLUTION 96
PROJECTION
	"init=epsg:23700"
END

OUTPUTFORMAT
	NAME png
	DRIVER "GD/PNG"
	MIMETYPE "image/png"
	IMAGEMODE RGB	# better image quality for photos
	FORMATOPTION  "INTERLACE=OFF"
	TRANSPARENT OFF
	EXTENSION "png"
END

WEB
	TEMPLATE "x_template.html"
	IMAGEPATH "/web/html/x/tmp/"
#	IMAGEPATH "/home/html/x/tmp/"
	IMAGEURL "/x/tmp/"
#	HEADER "x_header.html"
#	FOOTER "x_footer.html"
	MAXSCALEDENOM 100000
#	MINSCALEDENOM 100
#	ERROR "/x/hiba.html"
#	EMPTY "/x/hiba.html"
	METADATA
		wms_title "X WMS Server"
		wms_abstract "Several map layers for 10th district of Budapest"
#		wms_onlineresource "http://localhost/cgi-bin/mapserv?map=/home/html/x/pmapper/config/default/x201406.map&"
		wms_onlineresource "http://terkep.kobanya.hu/cgi-bin/mapserv?map=/web/html/x/pmapper/config/default/x201703.map&"
		wms_srs "EPSG:23700 EPSG:3857 EPSG:900913"
	END
END


